import{describe,it,expect}from"vitest";import{CENSUS_YEAR,LANGUAGE_REVEAL_LAYERS,CLASSICAL_LANGUAGES,validateLanguageData,getLanguagesUpToLayer,countAccumulatedLanguages}from"../../frontend/language-diversity-map/script.js";describe("Language Diversity Map Dataset Integrity (#582)",()=>{it("notes official Census of India data year (2011)",()=>{expect(CENSUS_YEAR).toBe(2011)}),it("contains at least 3 progressive reveal layers",()=>{expect(Array.isArray(LANGUAGE_REVEAL_LAYERS)).toBe(!0),expect(LANGUAGE_REVEAL_LAYERS.length).toBeGreaterThanOrEqual(3)}),it("validates language dataset structure across all layers",()=>{const e=validateLanguageData(LANGUAGE_REVEAL_LAYERS);expect(e.isValid).toBe(!0),expect(e.errors).toEqual([])}),it("includes top 5 scheduled languages in Layer 1",()=>{const e=LANGUAGE_REVEAL_LAYERS[0];expect(e.languages.length).toBe(5);const a=e.languages.map(e=>e.name);expect(a).toContain("Hindi"),expect(a).toContain("Bengali"),expect(a).toContain("Marathi"),expect(a).toContain("Telugu"),expect(a).toContain("Tamil")}),it("ensures every language entry has speaker counts, script, family, and regions",()=>{LANGUAGE_REVEAL_LAYERS.forEach(e=>{e.languages.forEach(e=>{expect(e).toHaveProperty("name"),expect(e).toHaveProperty("speakers"),expect(e).toHaveProperty("family"),expect(e).toHaveProperty("script"),expect(e).toHaveProperty("regions"),expect(e.regions.length).toBeGreaterThan(0)})})})}),describe("Layer Accumulation & Reveal Logic",()=>{it("accumulates 5 languages for Layer 1",()=>{const e=getLanguagesUpToLayer(1);expect(e.length).toBe(5)}),it("accumulates 12 languages for Layer 2 (5 + 7)",()=>{const e=getLanguagesUpToLayer(2);expect(e.length).toBe(12)}),it("accumulates 22 languages for Layer 3 (5 + 7 + 10)",()=>{const e=getLanguagesUpToLayer(3);expect(e.length).toBe(22)}),it("clamps layer boundaries to valid range 1-3",()=>{expect(countAccumulatedLanguages(0)).toBe(5),expect(countAccumulatedLanguages(10)).toBe(22)})});